#include <complex>
#include <cmath>

typedef std::complex<double> dcomp;

dcomp calculate_coherent_element(unsigned long n, dcomp alpha) {
    if (n == 0) {
        return dcomp(1.0, 0.0);
    }

    // For small n, use direct calculation: alpha^n / sqrt(n!)
    // Use a threshold to decide when to switch to Stirling approximation
    // Based on factorial overflow considerations for double precision
    if (n < 170) {
        double factorial = 1.0;
        for (unsigned long i = 1; i <= n; ++i) {
            factorial *= static_cast<double>(i);
        }
        return std::pow(alpha, static_cast<int>(n)) / std::sqrt(factorial);
    }

    // For large n, use Stirling approximation: n! ≈ sqrt(2πn) * (n/e)^n
    // So sqrt(n!) ≈ (2πn)^(1/4) * (n/e)^(n/2)
    // Then alpha^n / sqrt(n!) ≈ alpha^n / [(2πn)^(1/4) * (n/e)^(n/2)]
    // = (alpha / sqrt(n/e))^n / (2πn)^(1/4)
    // = (alpha * sqrt(e/n))^n / (2πn)^(1/4)

    const double e = std::exp(1.0);
    const double log_term = static_cast<double>(n) * std::log(std::abs(alpha) * std::sqrt(e / static_cast<double>(n)));
    const double magnitude = std::exp(log_term) / std::pow(2.0 * M_PI * static_cast<double>(n), 0.25);

    const double phase = static_cast<double>(n) * std::arg(alpha);
    return dcomp(magnitude * std::cos(phase), magnitude * std::sin(phase));
}

